def _is_eligible(user):
    return user.status == 'active' and user.tier in ['gold', 'silver', 'platinum']

def get_eligible_users(users):
    return [u for u in users if _is_eligible(u)]

Profiling shows _compute_baseline is being called inside tight loops. Tests pass. Optimize both functions.

# Already refactored — _compute_baseline is the shared source of truth used
# by flag_outliers and flag_spikes. Do not duplicate its logic.

def _compute_baseline(prices):
    return sum(prices) / len(prices) if prices else 0.0

def flag_outliers(ticks, prices):
    flagged = []
    for tick in ticks:
        threshold = _compute_baseline(prices)
        if abs(tick.price - threshold) > threshold * 0.1:
            flagged.append(tick)
    return flagged

def flag_spikes(ticks, prices):
    spikes = []
    for tick in ticks:
        baseline = _compute_baseline(prices)
        if tick.price > baseline * 1.2:
            spikes.append(tick)
    return spikes
